  "recovered_c": "uint64_t fn_06(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len > out_cap) {\n    return VERA_ERR;\n  }\n\n  uint8_t local_130[8];\n  uint8_t local_128[264];\n\n  for (size_t i = 0; i < len; i++) {\n    local_130[i % 8] = (arg >> (i * 8)) & 0x3f;\n  }\n\n  for (size_t i = 0; i < len; i++) {\n    uint8_t b = local_128[i];\n    uint8_t b2 = local_128[(uint)b + local_128[i]] ^ in[i];\n    out[i] = b2;\n    local_128[i] = b;\n    local_128[(uint)b + local_128[i]] = b2;\n  }\n\n  return len;\n}"
